class LocationSection extends StatefulWidget {
  const LocationSection({required this.caseId, required this.controller, required this.service, super.key});
  final String caseId; final EvidenceController controller; final CaseLocationService service;
  @override State<LocationSection> createState() => _LocationSectionState();
}
class _LocationSectionState extends State<LocationSection> {
  CaseLocation? location; RoadContext? road; bool busy = false; String? message;
  bool hydrated = false;
  @override void initState() { super.initState(); widget.controller.addListener(_maybeLoad); WidgetsBinding.instance.addPostFrameCallback((_) => _maybeLoad()); }
  @override void dispose() { widget.controller.removeListener(_maybeLoad); super.dispose(); }
  void _maybeLoad() { if (hydrated || widget.controller.items.isEmpty) return; hydrated = true; _load(); }
  Future<void> _load() async { final value = await widget.service.load(widget.caseId); final roads = await widget.service.loadRoadContext(widget.caseId); if (mounted) setState(() { location = value; road = roads; }); }
  Future<void> _fromEvidence() async { await _run(() async { CaseLocation? found; for (final evidence in widget.controller.items) { final candidate = await widget.service.evidenceGps(widget.caseId, evidence); if (candidate != null) { if (found != null && (found.latitude - candidate.latitude).abs() > .001) { message = 'Conflicting evidence GPS values found. No location was selected.'; return; } found = candidate; } } location = found; message = found == null ? 'No GPS location metadata found in this evidence.' : 'GPS candidate found. Confirm it explicitly before using it as the incident location.'; }); }
  Future<void> _current() async { await _run(() async { location = await widget.service.current(widget.caseId); message = location == null ? 'Current location unavailable or permission is required. No location was assigned.' : 'Current device location candidate. It may differ from the incident location.'; }); }
  Future<void> _run(Future<void> Function() action) async { if (busy) return; setState(() { busy = true; message = null; }); try { await action(); } finally { if (mounted) setState(() => busy = false); } }
  Future<void> _confirm() async { final value = location; if (value == null) return; await widget.service.confirm(value); setState(() => busy = true); final result = await widget.service.fetchRoadContext(value); await widget.service.saveRoadContext(result); if (mounted) setState(() { road = result; busy = false; message = 'Location confirmed from ${value.source.label}.'; }); }
  Future<void> _map() async { final base = location; final selected = await showDialog<LatLng>(context: context, builder: (_) => _MapPicker(initial: base == null ? null : LatLng(base.latitude, base.longitude))); if (selected != null && mounted) setState(() { location = CaseLocation(caseId: widget.caseId, latitude: selected.latitude, longitude: selected.longitude, source: CaseLocationSource.mapSelection, updatedAt: DateTime.now()); message = 'Map candidate selected. Confirm it before persistence.'; }); }
  @override Widget build(BuildContext context) => IrisCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('LOCATION & ROAD CONTEXT', style: Theme.of(context).textTheme.titleMedium), const SizedBox(height: IrisSpacing.sm), Text(location == null ? 'Incident location: Not established' : 'Incident location: ${location!.latitude.toStringAsFixed(6)}, ${location!.longitude.toStringAsFixed(6)}'), if(location != null) Text('Source: ${location!.source.label}'), const SizedBox(height: IrisSpacing.sm), Wrap(spacing: IrisSpacing.sm, runSpacing: IrisSpacing.xs, children: [OutlinedButton(onPressed: busy ? null : _fromEvidence, child: const Text('Detect from Evidence')), OutlinedButton(onPressed: busy ? null : _current, child: const Text('Use Current Location')), OutlinedButton(onPressed: busy ? null : _map, child: const Text('Select on Map')), const OutlinedButton(onPressed: null, child: Text('Search Location')), TextButton(onPressed: () => setState(() { location = null; road = null; message = 'Incident location: Not established'; }), child: const Text('Skip for Now'))]), if(location != null) FilledButton(onPressed: busy ? null : _confirm, child: const Text('Confirm Location')), if(message != null) Padding(padding: const EdgeInsets.only(top: IrisSpacing.sm), child: Text(message!)), const SizedBox(height: IrisSpacing.sm), Text('Road context: ${road?.status == 'AVAILABLE' ? 'Available' : 'Unavailable'}'), if(road?.status == 'AVAILABLE') ...road!.roads.take(3).map((r) => Text('${r.name ?? 'Unnamed road'} • ${r.roadClass ?? 'Class unavailable'} • lanes: ${r.lanes?.toString() ?? 'Not available'} • width: ${r.width?.toString() ?? 'Not available'}')), const Text('Map-derived context — verify against case evidence.'), if(road?.status == 'AVAILABLE' && location != null) _RoadPreview(context: road!, location: location!) ]));
}
class _MapPicker extends StatefulWidget { const _MapPicker({this.initial}); final LatLng? initial; @override State<_MapPicker> createState() => _MapPickerState(); }
class _MapPickerState extends State<_MapPicker> { LatLng? selected; @override Widget build(BuildContext context) { final center = widget.initial ?? const LatLng(0, 0); return AlertDialog(title: const Text('Select incident location'), content: SizedBox(width: 360, height: 420, child: FlutterMap(options: MapOptions(initialCenter: center, initialZoom: widget.initial == null ? 2 : 15, onTap: (_, point) => setState(() => selected = point)), children: [TileLayer(urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png', userAgentPackageName: 'com.iris.incidentreconstruction'), if(selected != null) MarkerLayer(markers: [Marker(point: selected!, width: 40, height: 40, child: const Icon(Icons.location_pin, color: Colors.red, size: 40))]), const RichAttributionWidget(attributions: [TextSourceAttribution('OpenStreetMap contributors')])])), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: selected == null ? null : () => Navigator.pop(context, selected), child: const Text('Use selected point'))]); } }
class _RoadPreview extends StatelessWidget { const _RoadPreview({required this.context, required this.location}); final RoadContext context; final CaseLocation location; @override Widget build(BuildContext _) => SizedBox(height: 180, child: FlutterMap(options: MapOptions(initialCenter: LatLng(location.latitude, location.longitude), initialZoom: 16, interactionOptions: const InteractionOptions(flags: InteractiveFlag.none)), children: [PolylineLayer(polylines: context.roads.map((r) => Polyline(points: r.coordinates.map((p) => LatLng(p[0], p[1])).toList(), strokeWidth: 3, color: Colors.amber)).toList()), MarkerLayer(markers: [Marker(point: LatLng(location.latitude, location.longitude), width: 28, height: 28, child: const Icon(Icons.location_pin, color: Colors.red))]) ])); }
